#this script is for my personal budget
setwd("C:/Users/Christian/Projects/Living/Financial/Budget/src")


#packages
library(tidyverse)

ref_month <- "05"
ref_yr <- "2026"

#expenses split 50/50. the amount will be halved in the statements with entries matching these descriptions
split_expenses <- c("SOBEYS  CHARLOTTETOWNPE", 
                    "PURPLE COW INTERNET IN HALIFAX NS", 
                    "DSMARLO DEVELOPME BUSENT",
                    "DSMARITIME ELEC BPYFAC",
                    "ATLANTIC SUPERSTORE CH CHARLOTTETOWNPE",
                    "NF  CHARLOTTETOWNPE",
                    "CONNOR KENNEDY S NO CHARLOTTETOWNPE")

#get path names for input data
cred_path <- paste("../data/credit_", ref_yr, ref_month, ".csv", sep="")
deb_path <- paste("../data/debit_", ref_yr, ref_month, ".csv", sep="")


#load the data
cred_tbl <- read_csv(cred_path, col_names = T, skip=2)
deb_tbl <- read_csv(deb_path, col_names = T, skip=3)



###FUNCTION: preprocess
###INPUT: list of datasets to concatenate into one dataset of the form:
###       Card | Transaction type (credit, debit) | date |  amount | description
preprocess <- function(input_data) {
  #credit statements are of the form:
  #Item #	| Card #	| Transaction Date	| Posting Date	 | Transaction Amount	| Description
  clean_cred <- input_data[[1]] %>% mutate(trans_type="debit") %>% 
    rename("card_num" = "Card #", "amount"="Transaction Amount", "date"="Transaction Date", "amount"="Transaction Amount") %>%
    select(-c("Item #", "Posting Date")) %>%
    filter(substr(date,5,6)==ref_month)
  
  
  
  clean_deb <- input_data[[2]] %>% rename("card_num" = "First Bank Card", "amount"="Transaction Amount", "date"="Date Posted",
                                          "trans_type"="Transaction Type") %>% filter(substr(date,5,6)==ref_month)
                            
  clean_tbl <- bind_rows(clean_cred, clean_deb) %>% mutate(amount=abs(amount), 
                                                           temp1=toupper(str_replace_all(Description, "[[:punct:]]", "")),
                                                           trans_type=toupper(trans_type)) %>%
                                                    mutate(temp2=str_replace_all(temp1," +"," ")) %>% 
                                                    mutate(Description=str_replace_all(temp2, "[0-9]+", "")) %>% select(-c("temp1", "temp2"))
}

input_data <- list(cred_tbl, deb_tbl)

clean_tbl <- preprocess(input_data=input_data)

#now we have clean_tbl of the following form:
#"card_num"    "date"        "amount"      "Description" "trans_type" 

#can join on description, then iterate through the transactions and ask for records that
#don't have a value for category.

if(file.exists("../data/description_dict.csv")){
  description_dict <- read_csv("../data/description_dict.csv")
}else{
  description_dict <- tibble(Description = character(),
                             category = character())
}

#add the category information from previous months
clean_tbl <- clean_tbl %>% left_join(description_dict, by="Description")

#iterate through the tibble and complete the "category" variable by asking 
#for each instance that wasn't filled by the left join
clean_tbl_filled <- clean_tbl %>% rowwise() %>%
    mutate(category=ifelse(is.na(category), readline(prompt=paste("What is the appropriate category for your purchase of ", amount, " with this description: '",Description,"' : ",sep="")),
                                                          category))


#update the description dictionary and write it to the data directory
description_dict <- clean_tbl_filled %>% 
  select(Description, category) %>% 
  bind_rows(description_dict) %>%  
  distinct()

write_csv(description_dict, path="../data/description_dict.csv")

#Apply factor of 1/2 to split expenses
clean_tbl_filled <- clean_tbl_filled %>% 
  mutate(amount=ifelse(is.na(Description), amount,
                       ifelse(Description %in% split_expenses, round(amount*0.5, digits = 2), amount)
                       )
         )


#write the data for the current month
arrange(clean_tbl_filled, desc(amount)) %>% 
  write_csv(path= paste("../data/spending_", ref_yr, ref_month, ".csv", sep=""))

#make changes if necessary, read it back in
clean_tbl_filled <- read_csv(paste("../data/spending_",ref_yr, ref_month, ".csv", sep=""))




for_bar_graph <- as.data.frame(clean_tbl_filled) %>% filter(category != "NA" & category != "Income")

ggplot(for_bar_graph, aes(x=category, y=amount, fill=category)) +
  geom_col(col="black")

as.data.frame(clean_tbl_filled) %>% 
  filter(category != "NA") %>%
  group_by(category) %>% 
  summarise(amount_spent=sum(amount)) %>% 
  arrange(desc(amount_spent))

as.data.frame(clean_tbl_filled) %>% 
  mutate(trans_type=tolower(trans_type)) %>% 
  filter(category != "NA") %>% 
  group_by(trans_type) %>%
  summarise(money_in=sum(amount))




#Compare this month's spending to a running average of previous months. 
all_spending <- list.files(path="../data", pattern = "^spending_") %>%
   map_df(~read_csv(paste("../data/", ., sep="")))
n_months=length(list.files(path="../data", pattern = "^spending_"))-1


all_spending <- all_spending %>% mutate(all_spending, date= as.Date(as.character(date), format="%Y%m%d"))

#add indicator for if an observation is from a past month
all_spending <- all_spending %>% mutate(past=ifelse(date < as.Date(paste("2026", ref_month, "01", sep=""), format="%Y%m%d"),1,0))

compare_to_past <- all_spending %>% 
  filter(category != "Income") %>% 
  group_by(past,category) %>% 
  summarise(money_spent=sum(amount/n_months)) %>% 
  mutate(money_spent=ifelse(past==0,money_spent*n_months,money_spent)) %>% 
  drop_na() 

past_plot <- ggplot(compare_to_past, aes(x=category, y=money_spent, fill=past)) + 
  geom_col(position = "dodge2")
past_plot


for_scatter <- all_spending %>% 
  mutate(ym=as.Date(paste0(format(date, "%Y%m"), "01"), format = "%Y%m%d")) %>% 
  filter(category != 'NA' & category !='Investments' & category !='Income' & category != 'Trips') %>%
  group_by(ym, category) %>% 
  summarise(amount=sum(amount))

ggplot(for_scatter, aes(x=ym, y=amount)) +
  geom_point() +
  facet_wrap(vars(category)) +
  coord_cartesian(ylim= c(0,1100)) + 
  geom_text(data=subset(for_scatter, amount > 1100),
            aes(x=ym, y=1100, label = "^")) +
  scale_x_date(date_breaks = "12 months", date_labels = "%Y-%m")


as.data.frame(clean_tbl_filled) %>% filter(category != "NA") %>%
  group_by(category) %>% summarise(amount_spent=sum(amount)) %>% arrange(category)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
